<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function sd_homepage_sanitize_bool( $value ) { return (bool) $value; }
function sd_homepage_sanitize_limit( $value ) { return min( 12, max( 1, absint( $value ) ) ); }
function sd_homepage_sanitize_percent( $value ) { return min( 100, max( 0, absint( $value ) ) ); }
function sd_homepage_sanitize_order( $value ) { $items = array_map( 'sanitize_key', explode( ',', (string) $value ) ); return implode( ',', array_values( array_intersect( $items, sd_homepage_section_keys() ) ) ); }
function sd_homepage_add_setting( $wp_customize, $id, $default, $sanitize, $label, $section, $type = 'text', $extra = array() ) { $wp_customize->add_setting( $id, array( 'default' => $default, 'sanitize_callback' => $sanitize ) ); $args = array_merge( array( 'label' => $label, 'section' => $section, 'type' => $type ), $extra ); $wp_customize->add_control( $id, $args ); }
function sd_homepage_customizer( $wp_customize ) {
	$wp_customize->add_panel( 'sd_homepage', array( 'title' => __( 'Social Discovery Homepage', 'social-discovery' ), 'priority' => 31 ) );
	$wp_customize->add_section( 'sd_home_general', array( 'title' => __( 'Homepage General', 'social-discovery' ), 'panel' => 'sd_homepage' ) );
	sd_homepage_add_setting( $wp_customize, 'sd_homepage_mode', 'native', 'sd_sanitize_select', __( 'Homepage rendering mode', 'social-discovery' ), 'sd_home_general', 'select', array( 'choices' => array( 'native' => __( 'Native sections', 'social-discovery' ), 'page-content' => __( 'Assigned page content', 'social-discovery' ) ) ) );
	sd_homepage_add_setting( $wp_customize, 'sd_homepage_order', sd_homepage_get( 'sd_homepage_order' ), 'sd_homepage_sanitize_order', __( 'Section order (comma-separated)', 'social-discovery' ), 'sd_home_general', 'text', array( 'description' => implode( ', ', sd_homepage_section_keys() ) ) );
	$wp_customize->add_section( 'sd_home_hero', array( 'title' => __( 'Hero', 'social-discovery' ), 'panel' => 'sd_homepage' ) );
	foreach ( array( 'sd_home_hero_enabled' => array( 'Enable hero', 'checkbox', 'sd_homepage_sanitize_bool' ), 'sd_home_hero_eyebrow' => array( 'Eyebrow', 'text', 'sanitize_text_field' ), 'sd_home_hero_heading' => array( 'Heading', 'text', 'sanitize_text_field' ), 'sd_home_hero_description' => array( 'Description', 'textarea', 'sanitize_textarea_field' ), 'sd_home_hero_primary_text' => array( 'Primary button text', 'text', 'sanitize_text_field' ), 'sd_home_hero_secondary_text' => array( 'Secondary button text', 'text', 'sanitize_text_field' ) ) as $id => $config ) { sd_homepage_add_setting( $wp_customize, $id, sd_homepage_get( $id ), $config[2], $config[0], 'sd_home_hero', $config[1] ); }
	foreach ( array( 'sd_home_hero_layout' => array( 'Layout', array( 'split' => 'Split', 'centered' => 'Centered', 'full-width' => 'Full width' ) ), 'sd_home_hero_alignment' => array( 'Text alignment', array( 'left' => 'Left', 'center' => 'Center' ) ) ) as $id => $config ) { sd_homepage_add_setting( $wp_customize, $id, sd_homepage_get( $id ), 'sd_sanitize_select', $config[0], 'sd_home_hero', 'select', array( 'choices' => $config[1] ) ); }
	foreach ( array( 'sd_home_hero_primary_url' => 'Primary button URL', 'sd_home_hero_secondary_url' => 'Secondary button URL' ) as $id => $label ) { sd_homepage_add_setting( $wp_customize, $id, '', 'sd_sanitize_url', $label, 'sd_home_hero', 'url' ); }
	$wp_customize->add_setting( 'sd_home_hero_image', array( 'default' => 0, 'sanitize_callback' => 'absint' ) ); $wp_customize->add_control( new WP_Customize_Media_Control( $wp_customize, 'sd_home_hero_image', array( 'label' => 'Hero image', 'section' => 'sd_home_hero', 'mime_type' => 'image' ) ) );
	$wp_customize->add_setting( 'sd_home_hero_background', array( 'default' => '#F8FAFC', 'sanitize_callback' => 'sanitize_hex_color' ) ); $wp_customize->add_control( new WP_Customize_Color_Control( $wp_customize, 'sd_home_hero_background', array( 'label' => 'Hero background', 'section' => 'sd_home_hero' ) ) );
	sd_homepage_add_setting( $wp_customize, 'sd_home_hero_overlay_opacity', 35, 'sd_homepage_sanitize_percent', 'Overlay opacity (%)', 'sd_home_hero', 'number', array( 'input_attrs' => array( 'min' => 0, 'max' => 100 ) ) );
	// Reusable section controls.
	$sections = array( 'groups' => array( 'Featured Communities', 'sd_home_groups_enabled', 'sd_home_groups_heading', 'sd_home_groups_limit', '', array() ), 'people' => array( 'Discover People', 'sd_home_people_enabled', 'sd_home_people_heading', 'sd_home_people_limit', '', array() ), 'interests' => array( 'Explore Interests', 'sd_home_interests_enabled', 'sd_home_interests_heading', 'sd_home_interests_limit', 'sd_home_interests_layout', array( 'pills' => 'Pills', 'grid' => 'Grid' ) ), 'discussions' => array( 'Public Discussions', 'sd_home_discussions_enabled', 'sd_home_discussions_heading', 'sd_home_discussions_limit', '', array() ), 'how' => array( 'How It Works', 'sd_home_how_enabled', 'sd_home_how_title', '', '', array() ), 'benefits' => array( 'Benefits', 'sd_home_benefits_enabled', 'sd_home_benefits_title', '', 'sd_home_benefits_layout', array( 'cards' => 'Cards', 'split' => 'Split', 'icons' => 'Icon grid' ) ), 'guidelines' => array( 'Community Guidelines', 'sd_home_guidelines_enabled', 'sd_home_guidelines_title', '', '', array() ), 'articles' => array( 'Latest Articles', 'sd_home_articles_enabled', 'sd_home_articles_title', '', '', array() ), 'cta' => array( 'Join CTA', 'sd_home_cta_enabled', 'sd_home_cta_title', '', 'sd_home_cta_layout', array( 'centered' => 'Centered', 'split' => 'Split', 'banner' => 'Full-width banner' ) ), 'faq' => array( 'FAQ', 'sd_home_faq_enabled', 'sd_home_faq_title', '', '', array() ), 'contact' => array( 'Contact CTA', 'sd_home_contact_enabled', 'sd_home_contact_title', '', '', array() ) );
	foreach ( $sections as $key => $config ) { $section_id = 'sd_home_' . $key; $wp_customize->add_section( $section_id, array( 'title' => $config[0], 'panel' => 'sd_homepage' ) ); sd_homepage_add_setting( $wp_customize, $config[1], sd_homepage_get( $config[1] ), 'sd_homepage_sanitize_bool', 'Enable section', $section_id, 'checkbox' ); sd_homepage_add_setting( $wp_customize, $config[2], sd_homepage_get( $config[2] ), 'sanitize_text_field', 'Section title', $section_id, 'text' ); if ( $config[3] ) { sd_homepage_add_setting( $wp_customize, $config[3], sd_homepage_get( $config[3] ), 'sd_homepage_sanitize_limit', 'Item limit', $section_id, 'number', array( 'input_attrs' => array( 'min' => 1, 'max' => 12 ) ) ); } if ( $config[4] && ! empty( $config[5] ) ) { sd_homepage_add_setting( $wp_customize, $config[4], sd_homepage_get( $config[4] ), 'sd_sanitize_select', 'Layout', $section_id, 'select', array( 'choices' => $config[5] ) ); } }
	foreach ( array( 'sd_home_groups_columns' => array( 'Groups columns', array( 1 => '1', 2 => '2', 3 => '3' ) ), 'sd_home_groups_sort' => array( 'Groups sorting', array( 'active' => 'Active', 'newest' => 'Newest', 'popular' => 'Popular' ) ), 'sd_home_people_columns' => array( 'People columns', array( 1 => '1', 2 => '2', 3 => '3', 4 => '4' ) ), 'sd_home_people_sort' => array( 'People sorting', array( 'active' => 'Active', 'newest' => 'Newest', 'random' => 'Random' ) ), 'sd_home_how_layout' => array( 'Steps layout', array( 'three' => 'Three steps', 'four' => 'Four steps' ) ) ) as $id => $config ) { $section = false !== strpos( $id, 'groups' ) ? 'sd_home_groups' : ( false !== strpos( $id, 'people' ) ? 'sd_home_people' : 'sd_home_how' ); sd_homepage_add_setting( $wp_customize, $id, sd_homepage_get( $id ), 'sd_sanitize_select', $config[0], $section, 'select', array( 'choices' => $config[1] ) ); }
	sd_homepage_add_setting( $wp_customize, 'sd_home_guidelines_page', 0, 'absint', 'Guidelines page', 'sd_home_guidelines', 'dropdown-pages' ); sd_homepage_add_setting( $wp_customize, 'sd_home_articles_category', true, 'wp_validate_boolean', 'Show category', 'sd_home_articles', 'checkbox' ); sd_homepage_add_setting( $wp_customize, 'sd_home_articles_date', true, 'wp_validate_boolean', 'Show date', 'sd_home_articles', 'checkbox' ); sd_homepage_add_setting( $wp_customize, 'sd_home_faq_items', sd_homepage_get( 'sd_home_faq_items' ), 'sanitize_textarea_field', 'FAQ items (question and answer on alternating lines)', 'sd_home_faq', 'textarea' ); sd_homepage_add_setting( $wp_customize, 'sd_home_contact_page', 0, 'absint', 'Contact page', 'sd_home_contact', 'dropdown-pages' );
	sd_homepage_add_setting( $wp_customize, 'sd_home_people_bio', false, 'wp_validate_boolean', 'Show biography', 'sd_home_people', 'checkbox' ); sd_homepage_add_setting( $wp_customize, 'sd_home_how_description', sd_homepage_get( 'sd_home_how_description' ), 'sanitize_textarea_field', 'Description', 'sd_home_how', 'textarea' ); sd_homepage_add_setting( $wp_customize, 'sd_home_articles_columns', 3, 'sd_homepage_sanitize_limit', 'Columns', 'sd_home_articles', 'number', array( 'input_attrs' => array( 'min' => 1, 'max' => 4 ) ) ); sd_homepage_add_setting( $wp_customize, 'sd_home_cta_description', sd_homepage_get( 'sd_home_cta_description' ), 'sanitize_textarea_field', 'Description', 'sd_home_cta', 'textarea' ); sd_homepage_add_setting( $wp_customize, 'sd_home_cta_primary_text', sd_homepage_get( 'sd_home_cta_primary_text' ), 'sanitize_text_field', 'Primary button text', 'sd_home_cta', 'text' ); sd_homepage_add_setting( $wp_customize, 'sd_home_cta_primary_url', '', 'sd_sanitize_url', 'Primary button URL', 'sd_home_cta', 'url' ); sd_homepage_add_setting( $wp_customize, 'sd_home_cta_secondary_text', sd_homepage_get( 'sd_home_cta_secondary_text' ), 'sanitize_text_field', 'Secondary button text', 'sd_home_cta', 'text' ); sd_homepage_add_setting( $wp_customize, 'sd_home_cta_secondary_url', '', 'sd_sanitize_url', 'Secondary button URL', 'sd_home_cta', 'url' ); $wp_customize->add_setting( 'sd_home_cta_background', array( 'default' => '#2563EB', 'sanitize_callback' => 'sanitize_hex_color' ) ); $wp_customize->add_control( new WP_Customize_Color_Control( $wp_customize, 'sd_home_cta_background', array( 'label' => 'Background', 'section' => 'sd_home_cta' ) ) );
}
add_action( 'customize_register', 'sd_homepage_customizer', 20 );
